"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "payments",
    "name": "payments-worker",
    "uid": "uid-deployment-payments-worker"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 10
    }
  },
  "expected_effect": "Allow the application more time to respond to liveness probes during startup, preventing premature restarts.",
  "rationale": "The liveness probe timeout (2s) is too short compared to the application's startup time (46s). Increasing the timeout to 10s would give the application sufficient time to initialize before the probe fails. The logs confirm the app took 46s to start and the probe failed due to a 2.3s response time, both exceeding the 2s timeout. Adjusting the timeout to 10s aligns with the observed startup time and resolves the probe failure during initialization.",
